#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick(int n): n(n), bit(n+1, 0) {}
    void add(int idx, int delta) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }
    int query(int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> parent(N+1, 0);
    vector<vector<int>> children(N+1);
    for (int i = 2; i <= N; ++i) {
        cin >> parent[i];
        children[parent[i]].push_back(i);
    }

    vector<int> size(N+1, 1), heavy(N+1, 0);
    for (int i = N; i >= 2; --i) {
        int p = parent[i];
        size[p] += size[i];
        if (heavy[p] == 0 || size[i] > size[heavy[p]]) {
            heavy[p] = i;
        }
    }

    vector<int> tin(N+1), tout(N+1), node_at_tin(N);
    int timer = 0;
    stack<pair<int,int>> st;
    st.push({1, 0});
    while (!st.empty()) {
        auto [u, state] = st.top(); st.pop();
        if (state == 0) {
            tin[u] = timer;
            node_at_tin[timer] = u;
            timer++;
            st.push({u, 1});
            for (int i = (int)children[u].size() - 1; i >= 0; --i) {
                st.push({children[u][i], 0});
            }
        } else {
            tout[u] = timer - 1;
        }
    }

    vector<int> head(N+1), pos(N+1), node_at_pos(N);
    int cur_pos = 0;
    stack<pair<int,int>> st2;
    st2.push({1, 1});
    while (!st2.empty()) {
        auto [u, h] = st2.top(); st2.pop();
        int cur = u;
        while (cur != 0) {
            head[cur] = h;
            pos[cur] = cur_pos;
            node_at_pos[cur_pos] = cur;
            cur_pos++;
            for (int v : children[cur]) {
                if (v != heavy[cur]) {
                    st2.push({v, v});
                }
            }
            cur = heavy[cur];
        }
    }

    vector<bool> active(N+1, false);
    for (int i = 1; i <= N; ++i) {
        if (!children[i].empty()) active[i] = true;
    }

    Fenwick fw(N);
    set<int> active_tins;
    for (int i = 1; i <= N; ++i) {
        if (active[i]) {
            fw.add(pos[i] + 1, 1);
            active_tins.insert(tin[i]);
        }
    }

    int Q;
    cin >> Q;
    while (Q--) {
        int type;
        cin >> type;
        if (type == 2) {
            int v;
            cin >> v;
            if (!active[v]) continue;
            int L = tin[v], R = tout[v];
            auto it = active_tins.lower_bound(L);
            while (it != active_tins.end() && *it <= R) {
                int u = node_at_tin[*it];
                if (u != v) {
                    active[u] = false;
                    fw.add(pos[u] + 1, -1);
                    it = active_tins.erase(it);
                } else {
                    ++it;
                }
            }
        } else {
            int v, k;
            cin >> v >> k;
            if (k == 0) {
                cout << v << '\n';
                continue;
            }
            int C;
            if (active[v]) C = k + 1;
            else C = k;
            int cur = v;
            int remaining = C;
            while (cur != 0) {
                int h = head[cur];
                int L = pos[h];
                int R = pos[cur];
                int base = fw.query(L);
                int cnt = fw.query(R + 1) - base;
                if (remaining > cnt) {
                    remaining -= cnt;
                    cur = parent[h];
                } else {
                    int kth = cnt - remaining + 1;
                    int lo = L, hi = R, ans = -1;
                    while (lo <= hi) {
                        int mid = (lo + hi) / 2;
                        int count = fw.query(mid + 1) - base;
                        if (count >= kth) {
                            ans = mid;
                            hi = mid - 1;
                        } else {
                            lo = mid + 1;
                        }
                    }
                    int u = node_at_pos[ans];
                    cout << u << '\n';
                    break;
                }
            }
        }
    }

    return 0;
}
